// GENERATED by a script from Wikimedia Commons metadata. Do not edit by hand.
// Every photo here has a free licence (CC BY, CC BY-SA, CC0, Free Art
// License, public domain or India's open government licence). The app shows
// "Photo: [author] · [licence]" and links to the file's page on Commons.

/// A photo from Wikimedia Commons.
class ChapterPhoto {
  /// Path under /wikipedia/commons/, e.g. `3/31/Ziro_valley.jpg`.
  final String path;
  final String caption;
  final String author;
  final String license;

  /// Width of the original file in pixels.
  final int width;
  const ChapterPhoto(
      this.path, this.caption, this.author, this.license, this.width);

  static const _base = 'https://upload.wikimedia.org/wikipedia/commons';

  /// Widths Wikimedia pre-renders. Other widths are slow or refused.
  static const steps = [330, 500, 960, 1280, 1920, 3840];

  String get _name => path.substring(path.lastIndexOf('/') + 1);
  String get _ext => _name.substring(_name.lastIndexOf('.') + 1).toLowerCase();

  /// Vector files can be rendered at any width.
  bool get _vector => _ext == 'svg';

  /// Video and TIFF originals can't be shown directly; only their
  /// rendered JPEG/PNG thumbnails can.
  bool get _thumbOnly =>
      _vector || const {'tif', 'tiff', 'webm', 'ogv'}.contains(_ext);

  /// The file's page on Wikimedia Commons (full credit and licence text).
  String get page => 'https://commons.wikimedia.org/wiki/File:$_name';

  String _thumb(int s) => switch (_ext) {
        'svg' => '$_base/thumb/$path/${s}px-$_name.png',
        'tif' || 'tiff' => '$_base/thumb/$path/lossy-page1-${s}px-$_name.jpg',
        'webm' || 'ogv' => '$_base/thumb/$path/${s}px--$_name.jpg',
        _ => '$_base/thumb/$path/${s}px-$_name',
      };

  /// The smallest pre-rendered copy at least [px] wide. When the original is
  /// narrower than that, the original itself (or, above 3840 px, the 3840
  /// copy). Never asks for a copy wider than the original, which Wikimedia
  /// refuses.
  String url(int px) {
    final usable = [
      for (final s in steps)
        if (_vector || s < width) s
    ];
    for (final s in usable) {
      if (s >= px) return _thumb(s);
    }
    if (_thumbOnly) return _thumb(usable.isEmpty ? steps.first : usable.last);
    return width > 3840 ? _thumb(3840) : '$_base/$path';
  }
}

